#!/usr/bin/env python3
"""Write-once final review decision and seal; bounded local files and Git reads only."""
import datetime, hashlib, json, platform, signal, subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parent
REPO=ROOT.parents[2]
signal.alarm(30)
def digest(b):return hashlib.sha256(b).hexdigest()
def binding(b):return {'bytes':len(b),'sha256':digest(b)}
def canonical(v):return json.dumps(v,sort_keys=True,separators=(',',':')).encode()
def put(n,v):
    with (ROOT/n).open('x') as f:f.write(json.dumps(v,indent=2,sort_keys=True)+'\n')
v=json.loads((ROOT/'verification-result.json').read_text())
assert not (ROOT/'verify-v2.stderr').read_bytes()
version=subprocess.run(['git','--version'],cwd=REPO,capture_output=True,check=True,timeout=10).stdout.decode().strip()
tree=subprocess.run(['git','--no-replace-objects','show','-s','--format=%T',v['source_revision']],cwd=REPO,capture_output=True,check=True,timeout=10).stdout.decode().strip()
assert tree==v['source_tree']
official={'schema':1,'elixir':{'url':'https://raw.githubusercontent.com/elixir-lang/elixir/v1.20.4/lib/elixir/lib/io.ex','file':'official/elixir-v1.20.4-io.ex','binding':binding((ROOT/'official/elixir-v1.20.4-io.ex').read_bytes()),'lines':[288,310],'finding':'binwrite delegates to file.write; exact-version docs warn that default Unicode stdio changes binary output'},'erlang':{'url':'https://www.erlang.org/doc/apps/stdlib/io.html#setopts/2','observed_doc_version':'OTP 29.1.2 / stdlib 8.1.1','not_exact_runtime_patch':True,'lines':[1233,1243],'finding':'encoding latin1 controls physical standard-output bytes; Unicode converts bytes 128-255 to UTF-8; setopts supports this change'},'raw_failed_export_retained':False,'data_model':'exact pinned Hex bytes decoded as latin1 then encoded utf8 match recorded output bytes and sha256','corrected_runtime_test_executed':False}
put('official-source-findings.json',official)
decision={'schema':1,'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':{'model':'gpt-6-astra','reasoning_effort':'xhigh','role':'fresh actual-failure difficult review'},'verdict':'actual-execution-amendment-advanced-select-byte-transparent-export-correction','source_revision':v['source_revision'],'source_tree':tree,'run_id':v['run_id'],'job_id':123023004128,'artifact_id':v['artifact_id'],'artifact_zip':v['zip'],'artifact_tree_digest_sha256':v['artifact_tree_digest_sha256'],'source_and_command_joins':{'control_files':4,'frozen_product_files':177,'product_tree_digest_sha256':v['product_digest'],'metadata_files':104,'helpers':7,'commands':37,'all_actual_stream_complete_flags':True,'missing_raw_stream':'command28 stdout .scratch/copy.bin unlinked before host SHA512 check'},'actual_passed_scope':['103 collector pure controls','exact immutable images and preparation isolation','actual narrow executable-tooling mount policy','seven-tool/VM/crypto/CA150 prerequisites','pinned TLS downloads and complete bootstrap helper','exclusive cross-mount Rebar copy, target hash and direct Rebar execution'],'first_new_failure':v['first_failure'],'discriminating_test':{'scope':'bounded public pinned artifact download plus inert byte transform; independently recomputed in Python','source_bytes':1133941,'transformed_bytes':1693010,'recorded_sha256':'9ec3f63426780b4b34d6486a64785e6e499fec9167ac7c81eaad6de7f0c195f6','exact_size_and_sha_match':True},'selected_correction':{'owner':'root implementation lane','file':'hosted/scripts/test-identity-network.py','method':'Collector.copy_file_out','change':'checked :io.setopts(:standard_io, encoding: :latin1) before checked IO.binwrite in the dedicated binary export invocation','must_preserve':['existing path allowlist and timeout/caps','selected immutable images/bootstrap/source','all checksum/size guards','mount/capability/network/ownership safeguards','all active holds'],'regression':'bounded all-256-byte/NUL/high-byte export length+hash in next selected remote preparation; same pinned Hex/Rebar real exports before unchanged workload; pure controls reject setopts failure/nonzero/incomplete output','evidence_retention':'retain rejected bootstrap export bytes within existing artifact cap; never relax checks'},'retired_alternatives':['checksum relaxation','image change','broader executable mounts','unchanged failure rerun','kernel-wide encoding change','new executable prerequisite'],'cleanup':v['cleanup'],'product_methods_run':0,'runtime_acceptance':False,'corrected_runtime_executed':False,'pending':v['not_run']+['fresh corrected actual execution and independent artifact acceptance','all native/process/custody/provider/customer/release/GA holds'],'local_writes':'verification/github-delivery-runtime-followup/network-review/ only','canonical_edits_commit_push_dispatch':False,'local_runtime_or_held_process_probes':False,'tools':{'git':version,'python':platform.python_version(),'transport':'connected GitHub tools and mcp__node_repl__js fetch; Node version not exposed in REPL'},'reviewer_errors_preserved':[{'file':'verify.stderr','reason':'first offline verifier reused expected for prerequisite mapping and failed at extraction; all preceding assertions passed; original script retained','replacement':'verify_artifact_v2.py','replacement_stdout':'verify-v2.stdout','replacement_stderr':'verify-v2.stderr'},{'receipt':'retention-receipt.json','reason':'first transport call used object file_uri; failed before network; corrected to download_url without printing or persisting URL'}],'command_receipts':[{'argv':['python3','-B','verification/github-delivery-runtime-followup/network-review/verify_artifact.py'],'timeout_seconds':52,'script_alarm_seconds':50,'exit_code':1,'stdout':'verify.stdout','stderr':'verify.stderr'},{'argv':['python3','-B','verification/github-delivery-runtime-followup/network-review/verify_artifact_v2.py'],'timeout_seconds':52,'script_alarm_seconds':50,'exit_code':0,'stdout':'verify-v2.stdout','stderr':'verify-v2.stderr'},{'argv':['python3','-B','verification/github-delivery-runtime-followup/network-review/seal.py'],'script_alarm_seconds':30,'git_timeout_seconds':10,'scope':'local final decision/manifest only'}]}
put('decision.json',decision)
files={}
for p in sorted(ROOT.rglob('*')):
    assert not p.is_symlink()
    if p.is_file():files[str(p.relative_to(ROOT))]=binding(p.read_bytes())
assert 'packet-manifest.json' not in files
packet={'schema':1,'scope':'write-once actual failed identity runtime review; inert evidence only','files':files,'tree_digest_sha256':digest(canonical(files))}
put('packet-manifest.json',packet)
print(json.dumps({'files':len(files),'tree_digest_sha256':packet['tree_digest_sha256'],'packet_manifest':binding((ROOT/'packet-manifest.json').read_bytes()),'decision':binding((ROOT/'decision.json').read_bytes()),'verdict':decision['verdict'],'methods_run':0},indent=2))
